import{f as p,a as d,b}from"./chunks/food.BnY_bO_Z.js";import{F as e}from"./chunks/Food.1tN_DyEH.js";import{_ as i}from"./chunks/LinkTravelogue.vue_vue_type_script_setup_true_lang.DnixFauB.js";import{C as u,o as m,c as h,j as l,a as r,E as t,a5 as o,k as s}from"./chunks/framework.CnBNXlt7.js";import"./chunks/el-tooltip.DYy5KEUW.js";import"./chunks/base.C5rmQS7v.js";import"./chunks/use-form-item.DAqnwDzZ.js";import"./chunks/index.C40O6kqa.js";import"./chunks/use-global-config.CsZ30_Xh.js";import"./chunks/el-button.G5aj6r1f.js";import"./chunks/icon.C4nw7RXS.js";import"./chunks/dayjs.min.DTWwpTri.js";import"./chunks/travelogue.BgrUIWBQ.js";import"./chunks/utils.Crj2JTAd.js";const w=JSON.parse('{"title":"广东","description":"","frontmatter":{},"headers":[],"relativePath":"trip/china/guangdong/index.md","filePath":"trip/china/guangdong/index.md","lastUpdated":1753026920000}'),_={name:"trip/china/guangdong/index.md"},D=Object.assign(_,{setup(f){return(k,a)=>{const n=u("Badge");return m(),h("div",null,[a[3]||(a[3]=l("h1",{id:"广东",tabindex:"-1"},[r("广东 "),l("a",{class:"header-anchor",href:"#广东","aria-label":'Permalink to "广东"'},"​")],-1)),a[4]||(a[4]=l("h2",{id:"广州",tabindex:"-1"},[r("广州 "),l("a",{class:"header-anchor",href:"#广州","aria-label":'Permalink to "广州"'},"​")],-1)),t(i,{city:"广州"}),a[5]||(a[5]=o('<h3 id="攻略" tabindex="-1">攻略 <a class="header-anchor" href="#攻略" aria-label="Permalink to &quot;攻略&quot;">​</a></h3><details class="details custom-block"><summary>不愿透露姓名的群友推荐</summary><p>广州特色，各类嫁女饼（叉烧酥，蛋黄酥，莲蓉酥等等），云吞面，白切鸡，烧鹅，拉肠，虾饺，烧麦，猪脚姜</p><blockquote><p>嫁女饼是以前广州嫁女的时候，回礼给各位来宾的饼 广州还有各类凉茶，炖汤店，各类汤粉面</p></blockquote><p>地铁二号线，市二宫站，同福中路开始打卡一直到同福东都能吃好几种</p><blockquote><p>“赞记”“安乐炖品”“芬芳甜品”“无名牛腩粉”“燊记面店”</p></blockquote><p>市二宫地铁站D口出来，对面就有“赞记饼家”，买各类的老广烘焙饼，嫁女饼，糯米糍，酥皮面包等<br> 然后，再往前100米左右，回来对面马路，再到芬芳甜品，糖不甩和芒果糖水，还有煎粽子。芬芳的绿豆沙汤圆也好吃<br> 然后再往前100左右，对面就是“安乐炖品”几十年的老店，炖品店里的饭都很好吃，可以试试的<br> 同一方向往前，还有“无名”牛腩粉<br> 然后往前走~~同福东，有“燊记面店”牛三星，和猪油捞面，绝配，其余的面食都很可以<br> 然后，对面有熊记鸡粥，拉肠和粥都一绝</p><p>其实广州地道食品，都在老四区，东山，荔湾，越秀，海珠，其余的都是后期的，都是新派东西。找吃的，围着老四区就可以了</p><p>上下九有宝华面店，陈添记鱼皮，还有一家无名鱼蛋店，还有冰室，还有长寿面，还有多宝路的“冰之恋”只做冰镇</p><p>广州主要五类东西 甜品 粤菜 （早茶）烧味 啫啫煲 打边炉</p><p>千万别上广州塔，想去高处看夜景的话，可以去西塔楼顶的酒吧</p></details><div class="tip custom-block"><p class="custom-block-title">推荐店</p><p>炳胜品味<br> 百花甜品店 莲籽堂·广式现煲糖水铺·鲜烘新中点 甜心妈妈星级甜品<br> 利苑早茶 点都德 廣御點<br> 黑珍珠一钻餐厅 广州文华东方酒店·江<br> 黑珍珠三钻餐厅 白天鹅宾馆-玉堂春暖餐厅<br> 泰香米泰国餐厅(广州番禺天河城店)<br> 番禺：肥家大排档 寿司郎 潮发<br> 围仔饮食店(鹅煲)</p></div><h3 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h3><p>广州著名小食有哪些？地道的店在哪里？ - 铁血中锋郭四娘的回答 - 知乎 <a href="https://www.zhihu.com/question/19752381/answer/105159494" target="_blank" rel="noreferrer">https://www.zhihu.com/question/19752381/answer/105159494</a></p><div class="warning custom-block"><p class="custom-block-title">有什么避雷的店</p><p>抖音搜到的，基本都踩雷</p></div><h2 id="深圳" tabindex="-1">深圳 <a class="header-anchor" href="#深圳" aria-label="Permalink to &quot;深圳&quot;">​</a></h2>',7)),t(i,{city:"深圳"}),a[6]||(a[6]=l("h2",{id:"珠海",tabindex:"-1"},[r("珠海 "),l("a",{class:"header-anchor",href:"#珠海","aria-label":'Permalink to "珠海"'},"​")],-1)),t(i,{city:"珠海"}),a[7]||(a[7]=o('<h3 id="出行" tabindex="-1">出行 <a class="header-anchor" href="#出行" aria-label="Permalink to &quot;出行&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">前往香港</p><p>喜欢坐船的可以在<strong>九州港</strong>码头，坐船去香港，建议直接到<strong>港澳码头</strong>，普通舱就可以，￥180，发船后如果窗边有空位可以去窗边看看的。船其实没有港珠澳大桥的大巴快的，大巴时速75左右，船的时速基本在60，激起的浪花比较大，玻璃基本都挂满了水。</p><p>推荐港珠澳大桥穿梭巴士，微信公众号<strong>港珠澳大桥穿梭巴士</strong>可以直接购买，你也可以看看实时汇率，看看人民币购买便宜还是港币购买便宜。</p></div><div class="tip custom-block"><p class="custom-block-title">前往澳门</p><p>如果你在珠海站附近，步行即可，青茂口岸/拱北口岸都可，口岸外面的小店都会有寄存服务的，可以去问问</p></div><h3 id="酒店" tabindex="-1">酒店 <a class="header-anchor" href="#酒店" aria-label="Permalink to &quot;酒店&quot;">​</a></h3><p>200以下的酒店都很垃圾的，脏乱差，如果想体验好就住贵的。但是住贵的话，就不要考虑珠海了，直接住港澳吧。</p><h3 id="吃喝" tabindex="-1">吃喝 <a class="header-anchor" href="#吃喝" aria-label="Permalink to &quot;吃喝&quot;">​</a></h3><p>没什么吃喝推荐，都比较拉跨</p><h3 id="玩乐" tabindex="-1">玩乐 <a class="header-anchor" href="#玩乐" aria-label="Permalink to &quot;玩乐&quot;">​</a></h3><p>没有仔细游玩</p><h2 id="潮汕地区" tabindex="-1">潮汕地区 <a class="header-anchor" href="#潮汕地区" aria-label="Permalink to &quot;潮汕地区&quot;">​</a></h2><p>计划：深圳-汕头，-&gt; 潮州 -&gt; 揭阳，揭阳飞机飞走</p>',11)),t(i,{city:"汕头"}),a[8]||(a[8]=l("h3",{id:"汕头",tabindex:"-1"},[r("汕头 "),l("a",{class:"header-anchor",href:"#汕头","aria-label":'Permalink to "汕头"'},"​")],-1)),t(i,{city:"汕头"}),a[9]||(a[9]=o('<ul><li>小公园：商业街，各种汕头照片网图都在这里可以找到</li><li>妈祖庙</li><li>老妈宫戏台</li><li>屿岛旅游区（没有去过）</li><li>陈慈簧故居（没有去过）</li><li>汕头老城</li><li>开埠文化馆（外面路过）</li></ul><p>南澳岛：长山尾灯塔、田仔地质公园、青澳湾、南澳北回归线标志·自然之门、展南亭、蛴仔澎、三囱崖灯塔<br> 可以参考游记，因为天气不太好，没有在各个景点驻足，坐公交环线，在公交车上逛完整个岛</p><h3 id="潮州" tabindex="-1">潮州 <a class="header-anchor" href="#潮州" aria-label="Permalink to &quot;潮州&quot;">​</a></h3>',3)),t(i,{city:"潮州"}),a[10]||(a[10]=o('<p>潮汕茶馆品功夫茶，观潮剧，体验潮汕慢生活，建议品尝特色美食，老牌牛杂和原味鱼生。</p><ul><li>广济门城楼</li><li>牌坊街：特色商业街，除了牌坊其他地方全国到处都是</li><li>广济桥</li><li>潮州开元寺（未去）</li><li>潮州古城</li><li>许驸马府（要门票，非常小，没有选择参观，就在外面看看）</li><li>韩愈纪念馆（未去）</li></ul><h3 id="揭阳" tabindex="-1">揭阳 <a class="header-anchor" href="#揭阳" aria-label="Permalink to &quot;揭阳&quot;">​</a></h3>',3)),t(i,{city:"揭阳"}),a[11]||(a[11]=l("h2",{id:"佛山",tabindex:"-1"},[r("佛山 "),l("a",{class:"header-anchor",href:"#佛山","aria-label":'Permalink to "佛山"'},"​")],-1)),t(e,{foods:s(p)},null,8,["foods"]),a[12]||(a[12]=l("div",{class:"tip custom-block"},[l("p",{class:"custom-block-title"},"王刚美食推荐"),l("p",null,[r("志兴旺美食"),l("br"),r(" 有记餐厅")])],-1)),a[13]||(a[13]=l("h2",{id:"河源",tabindex:"-1"},[r("河源 "),l("a",{class:"header-anchor",href:"#河源","aria-label":'Permalink to "河源"'},"​")],-1)),t(i,{city:"河源"}),a[14]||(a[14]=o('<h3 id="游玩" tabindex="-1">游玩 <a class="header-anchor" href="#游玩" aria-label="Permalink to &quot;游玩&quot;">​</a></h3><p><strong>推荐</strong>：鳄湖公园、龟峰塔、龟峰公园、河源市博物馆、河源恐龙博物馆、客家文化公园、河源市图书馆<br><strong>避雷</strong>：太平古街<br><em>尚未探索</em>：亚洲第一高喷泉、农夫山泉工厂、林寨古村落、霍山旅游风景区、苏家围客家乡村旅游区</p><h3 id="美食" tabindex="-1">美食 <a class="header-anchor" href="#美食" aria-label="Permalink to &quot;美食&quot;">​</a></h3>',3)),t(e,{foods:s(d)},null,8,["foods"]),a[15]||(a[15]=l("p",null,"千万别吃",-1)),l("ul",null,[l("li",null,[a[0]||(a[0]=r("新明猪脚粉 ",-1)),t(n,{type:"warning",text:"人均 ¥20"}),a[1]||(a[1]=r()),t(n,{type:"tip",text:"猪脚粉"}),a[2]||(a[2]=r("猪脚没有卤过，直接熬的，口感一般。胡椒粉加的多，难吃。",-1))])]),a[16]||(a[16]=l("p",null,"尚未探索",-1)),a[17]||(a[17]=l("ul",null,[l("li",null,"五指毛桃鸡；砂锅焗法偏咸香口，奶香浓郁，焦香鸡皮好评！客家菜，还有紫金八刀汤和酿豆腐，推荐"),l("li",null,"汤萝卜粄和糯米饭📍店名水库人家"),l("li",null,"瑶柱云吞📍牛哥云吞")],-1)),a[18]||(a[18]=l("h2",{id:"梅州",tabindex:"-1"},[r("梅州 "),l("a",{class:"header-anchor",href:"#梅州","aria-label":'Permalink to "梅州"'},"​")],-1)),t(i,{city:"梅州"}),a[19]||(a[19]=l("h3",{id:"美食-1",tabindex:"-1"},[r("美食 "),l("a",{class:"header-anchor",href:"#美食-1","aria-label":'Permalink to "美食"'},"​")],-1)),t(e,{foods:s(b)},null,8,["foods"]),a[20]||(a[20]=o('<p>美食必吃<br> 腌面+三及第汤，一口面一口汤，满足感爆棚。还有客家猪/牛肉丸，Q弹有嚼劲。各类粄类（笋粄、艾粄、萝卜粄、发粄），丰顺捆粄，来梅州一定要尝尝梅州腌面，带着炸蒜酥的香气吃面时配上三及第汤，堪称绝配。来梅州一趟，当然不能错过腌面煮汤啦❗️ 枸杞菜三及第是标配🍜 用猪油拌的腌面加上炸蒜蓉超级香！🔥 👉新宜家面馆，大埔腌面 随便找一家腌面店都不错👏</p><p>注意看看三及第是什么，可能不合口味。</p><details class="details custom-block"><summary>尚未探索</summary><p>围龙屋星园酒家 📍三角镇富奇路190号 由百年围龙屋打造的梅州特色餐厅，每个细节彰显着独特客家文化魅力，不管从屋顶屋角雕饰还是房间壁画都蕴含着浓郁客家文化元素，适合客家美食打卡和拍照📷 ✨推荐：芝麻鸡，手磨豆腐，算盘子</p><p>1⃣️谢记鱼头煮粉 📍嘉应东路金良新村A栋103号 油炸过的鱼头放下去熬汤，熬出来的鱼汤奶白且鲜甜😋喜欢吃鱼的朋友不要错过❗️如果不想吃粉可以单点鱼头汤</p><p>2⃣️富奇路烧卖店 / 勤燕烧麦 / 虹桥烧麦 这几家都是本地人推荐的烧麦店❗️ 用猪肉，笋干和香菇包裹的薄薄烧卖🥟 朋友可以选一家尝试一下😆</p><p>3⃣️金山牛杂（总店） 📍凌风西路16号 来梅州必吃之一❗️ 跟广东其他地方吃到的牛杂是不同口感的，是冷吃牛杂，没有汤汁🥩值得朋友们来吃上这一口😍</p><p>4⃣️丰顺捆粄（百花洲店）/老邱捆粄 📍美凤路4-1号 一捆捆的皮薄馅足，各种口味都具备✌️ 还有肠粉 炖汤随意搭配 谁不爱啊👍</p><p>📍三妹老屋新鲜焗盐鸡 💰人均45 👍🏻推荐菜：盐焗鸡，鸡杂米粉 最好提前45分钟打电话预约，现点现做要等很久</p><p>📍春香早餐店 💰人均10元 👍🏻推荐菜：三及第，猪腰汤，腌面，腌米粉 1份汤➕1份主食套餐总共10元，分量很足，这家的腌面和米粉口感偏硬，适合喜欢筋道口感的人。这家的内脏都处理得特别干净，没有一点异味。不喜欢内脏的也有纯瘦肉汤可选，吃得出材料都非常新鲜❗️</p><p>📍市塘唇萧屋烧麦 💰人均7元 👍🏻推荐菜：烧麦，腌水饺，三及第 本地居民推荐早餐店，烧卖2元/4颗，一口一颗的量，邻桌的食客都是每人三碟起点。这一家的三及第是放咸菜而不是枸杞叶。</p><p>📍大埔笋粄算盘子 💰人均2元 👍🏻推荐菜：忆子粄，鲜笋粄、笋干粄 位于老街的一家小吃店，各种大埔经典小吃，笋粄豆粄，均价2元，可以每种买一个尝尝，味道都不一样！</p><p>📍润心客家小吃 💰人均15 👍🏻推荐菜：味酵粄、牛肉丸、牛杂、算盘子 一定要点这家的牛肉丸，是用牛肉粒做的，和潮汕牛肉丸完全不同，非常特别‼️</p><p>📍松口家常菜馆 💰人均15 👍🏻推荐菜：番茄牛肉汤，猪肉丸汤，腌老鼠粄，炸丸子 就在这次我们住的酒店附近，番茄牛肉汤和猪肉丸汤都很鲜，炸丸子外酥里糯。</p><p>📍顾园饭店 💰人均60 👍🏻推荐菜：腌牛肉，蒸鲜腐竹，咸菜炒猪肠，炒米粉 家庭饭店，桌子不多，最好提前打电话订位，尤其推荐腌牛肉和蒸鲜腐竹，腐竹豆香味浓郁，在别的地方从没吃到过！</p></details><h3 id="游玩-1" tabindex="-1">游玩 <a class="header-anchor" href="#游玩-1" aria-label="Permalink to &quot;游玩&quot;">​</a></h3><p><strong>推荐</strong>：千佛塔、中国客家博物馆、泮坑风景区、梅江<br><strong>避雷</strong>：东山书院、江北老街、油罗街、客天下客家小镇景区<br><em>尚未探索</em>：梅州学宫</p>',5))])}}});export{w as __pageData,D as default};
